function editProfile() { const data = current().profile || {}; const selected = value => data.sexForCalculation === value ? 'selected' : ''; const activity = value => data.activityLevel === value ? 'selected' : ''; const equipment = value => data.equipmentAccess === value ? 'selected' : ''; return shell(`<section class="onboarding"><span class="eyebrow">Datos personales</span><div class="form-card"><h2>Actualiza tus datos.</h2><p>Estos cambios se guardan en tu perfil. Tu plan actual no se reemplazará automáticamente.</p><div class="field-grid"><label class="field">Edad<input data-profile-field="age" type="number" min="16" max="90" value="${data.age || ''}" required></label><label class="field">Estatura (cm)<input data-profile-field="heightCm" type="number" min="120" max="230" value="${data.heightCm || ''}" required></label><label class="field">Peso actual (lb)<input data-profile-field="weightLb" type="number" min="70" max="500" step="0.1" value="${data.weightLb || ''}" required></label><label class="field">Calorías objetivo/día<input data-profile-field="targetCalories" type="number" min="1200" max="4000" step="25" value="${data.targetCalories || ''}" required></label><label class="field">Sexo para cálculo<select data-profile-field="sexForCalculation"><option ${selected('Prefiero no decir')}>Prefiero no decir</option><option ${selected('Mujer')}>Mujer</option><option ${selected('Hombre')}>Hombre</option></select></label><label class="field full">Actividad diaria<select data-profile-field="activityLevel"><option ${activity('Sedentaria')}>Sedentaria</option><option ${activity('Ligera')}>Ligera</option><option ${activity('Moderada')}>Moderada</option><option ${activity('Alta')}>Alta</option></select></label><label class="field full">Equipo disponible<select data-profile-field="equipmentAccess"><option ${equipment('Sin equipo')}>Sin equipo</option><option ${equipment('Bandas o mancuernas')}>Bandas o mancuernas</option><option ${equipment('Gimnasio completo')}>Gimnasio completo</option></select></label><label class="field full">Limitaciones o molestias (opcional)<input data-profile-field="limitations" value="${data.limitations || ''}" placeholder="Ej. molestia de rodilla, evitar saltos"></label></div><div class="notice">Para cambiar objetivo, nivel, días, tiempo o alimentación y crear un plan nuevo, usa “Rehacer evaluación y crear plan”.</div><div class="form-actions"><button class="btn outline" data-route="profile">Cancelar</button><button class="btn lime" data-action="save-profile">Guardar mis datos</button></div></div></section>`, true); }
function profile() { const user = current(); const data = user.profile || {}; const branches = user.branches || []; const mainBranch = branches.find(branch => branch.id === data.homeBranchId); const historyCount = user.planHistory?.filter(item => item.status === 'archived').length || 0; const field = (label, value) => `<span><b>${label}</b>${value || 'Pendiente'}</span>`; const branchControl = branches.length ? `<section class="profile-branch"><div><span class="eyebrow">Tu sede de entrenamiento</span><h3>Sucursal principal</h3><p>Define el equipo disponible para tus próximos planes, sin repetir tu evaluación.</p></div><label>Sucursal<select data-profile-home-branch>${branches.map(branch => `<option value="${branch.id}" ${branch.id === data.homeBranchId ? 'selected' : ''}>${branch.name}</option>`).join('')}</select></label><button class="btn lime" data-action="save-home-branch">Guardar sucursal</button><small>Actual: ${mainBranch?.name || 'Pendiente'}. Tu plan actual no cambiará.</small></section>` : `<section class="profile-branch empty"><b>Sucursal principal</b><p>Aún no hay sucursales activas disponibles.</p></section>`; return shell(`<section class="onboarding profile-page"><span class="eyebrow">Perfil</span><div class="form-card"><h2>${user.name}</h2><p>${user.email}</p>${branchControl}<div class="profile-data profile-data-expanded">${field('Objetivo', data.goal)}${field('Edad', data.age ? `${data.age} años` : '')}${field('Sexo para cálculo', data.sexForCalculation)}${field('Estatura', data.heightCm ? `${data.heightCm} cm` : '')}${field('Peso actual', data.weightLb ? `${data.weightLb} lb` : '')}${field('Objetivo diario', data.targetCalories ? `${data.targetCalories} kcal` : '')}${field('Actividad diaria', data.activityLevel)}${field('Equipo', data.equipmentAccess)}${field('Plan', data.days ? `${data.days} por semana` : '')}${field('Sesiones', `${user.workouts.length} registradas`)}</div>${data.limitations ? `<div class="profile-limitations"><b>Consideraciones físicas</b><span>${data.limitations}</span></div>` : ''}<div class="profile-actions"><button class="btn outline" data-route="plan-history">Historial de planes${historyCount ? ` (${historyCount})` : ''}</button><button class="btn lime" data-route="edit-profile">Actualizar mis datos</button><button class="btn outline" data-action="restart">Rehacer evaluación y crear plan</button></div></div></section>`, true); }
function admin() { const user = current(); if (!user || user.role === 'user') return shell('<section class="empty-state"><h1>Acceso restringido.</h1><p>Esta pantalla es solo para personal autorizado.</p><button class="btn lime" data-route="dashboard">Volver al inicio</button></section>', true); if (user.role === 'admin') return shell('<section class="admin-page"><div class="detail-head"><div><span class="eyebrow">Administración</span><h1>Gestiona FormaIA.</h1><p class="subhead">Usuarios, catálogos, membresías y pagos de la operación.</p></div><button class="btn outline" data-route="dashboard">Volver al inicio</button></div><div data-admin-panel class="admin-loading">Cargando administración…</div></section>', true); const label = user.role === 'branch_manager' ? 'Gerencia de sucursal' : 'Recepción'; const description = user.role === 'branch_manager' ? 'Consulta y opera únicamente las sucursales que tienes asignadas.' : 'Valida entradas y registra cobros solo en las sucursales que tienes asignadas.'; return shell(`<section class="admin-page"><div class="detail-head"><div><span class="eyebrow">${label}</span><h1>Operación de sucursal.</h1><p class="subhead">${description}</p></div></div><div data-reception-panel class="admin-loading"><div class="admin-tabs" role="tablist"></div>Cargando operación…</div></section>`, true); }

const standardAdmin = admin;
admin = function () { const user = current(); if (['manager', 'branch_manager'].includes(user?.role)) return shell('<section class="admin-page"><div class="detail-head"><div><span class="eyebrow">Gerencia</span><h1>Gestiona FormaIA y sus ingresos.</h1><p class="subhead">Acceso completo a la administración y al dashboard de reportes.</p></div><button class="btn outline" data-route="dashboard">Volver al inicio</button></div><div data-admin-panel class="admin-loading">Cargando administración…</div></section>', true); return standardAdmin(); };
function render() { if (['dashboard', 'workout', 'nutrition', 'progress', 'progress-history', 'record', 'profile', 'edit-profile', 'plan-history', 'admin'].includes(state.route) && (!current() || (current().role === 'user' && !plan()))) state.route = current() ? (current().role === 'user' ? 'onboarding' : 'admin') : 'landing'; const view = { landing, auth, onboarding, dashboard, workout, nutrition, progress, 'progress-history': progressHistory, record, profile, 'edit-profile': editProfile, 'plan-history': planHistory, admin }[state.route] || landing; root.innerHTML = view(); bind(); }
window.FormaIAClientSession = { user: () => LocalData.user(), setUser: (user, route) => { LocalData.save({ users: { [user.id]: user }, session: user.id }); state.route = route || (user.role !== 'user' ? 'admin' : user.plan ? 'dashboard' : 'onboarding'); render(); }, patchUser: patch => { const user = LocalData.user(); if (!user) return; LocalData.put({ ...user, ...patch }); render(); }, navigate: route => { state.route = route; render(); }, clear: () => { LocalData.save({ users: {}, session: null }); state.route = 'landing'; render(); } };
function toast(message) { const node = document.querySelector('#toast'); node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2800); }
function fields(selector) { return Object.fromEntries([...document.querySelectorAll(selector)].map(node => [node.dataset.auth || node.dataset.input || node.dataset.progress, node.value])); }
