  if (type === 'back') { state.step--; render(); return; }
  if (type === 'next') { if (state.step === 1 && !state.draft.goal) { toast('Elige un objetivo para continuar.'); return; } if (state.step === 4 && (!Number.isInteger(Number(state.draft.targetCalories)) || Number(state.draft.targetCalories) < 1200 || Number(state.draft.targetCalories) > 4000)) { toast('Indica un objetivo diario entre 1,200 y 4,000 kcal.'); return; } if (state.step < 4) { state.step++; render(); return; } const user = current(); user.profile = window.FormaIAData?.createProfile(state.draft) || { ...state.draft }; user.plan = buildPlan(user.profile); LocalData.put(user); state.route = 'dashboard'; render(); toast('Tu plan personalizado está listo ✦'); return; }
  if (type === 'start-workout') { state.active = true; startTimer(); render(); toast('Temporizador iniciado. ¡A tu ritmo!'); return; }
  if (type === 'pause-workout') { if (state.workoutTimer.interval) { pauseTimer(); toast('Temporizador en pausa.'); } else { startTimer(); toast('Temporizador reanudado.'); } window.dispatchEvent(new CustomEvent('formaia:timer', { detail: window.FormaIAWorkout.timerState() })); render(); return; }
  if (type === 'save-set') { const source = event?.currentTarget; if (!source) return; const row = source.closest('[data-set-row]'); const weightLb = row?.querySelector('[data-set-weight]')?.value || ''; const repetitions = row?.querySelector('[data-set-repetitions]')?.value || ''; const durationSeconds = row?.querySelector('[data-set-duration]')?.value || ''; if (!weightLb && !repetitions && !durationSeconds) { toast('Registra el peso, las repeticiones o los segundos de la serie.'); return; } const key = `${source.dataset.exerciseIndex}-${source.dataset.setNumber}`; state.completedSets[key] = { weightLb, repetitions, durationSeconds }; source.textContent = '✓ Guardada'; source.closest('.set-row')?.classList.add('is-saved'); toast('Serie guardada.'); return; }
